    pub(crate) fn remove_terminal_catalog_for_test(
        &self,
        terminal_id: &TerminalPublicId,
    ) -> Option<Arc<Surface>> {
        let mut state = self.state.lock().unwrap();
        let removed = state.terminal_catalog.remove(terminal_id)?;
        if let Some(runtime_id) = removed.terminal_runtime_id() {
            state.terminal_catalog_by_runtime.remove(&runtime_id);
        }
        Some(removed)
    }

    /// Resolve a process-stable terminal UUID and one live view placement.
    /// A catalog-owned terminal with zero views resolves successfully with a
    /// null surface. This is lookup-only and never creates a replacement shell.
    pub fn resolve_terminal(
        &self,
        terminal_id: &str,
    ) -> anyhow::Result<Option<TerminalResolution>> {
        validate_terminal_hex(terminal_id, "invalid_terminal_id")?;
        let (terminal, terminal_revision) = {
            let registry = self.workspace_registry.lock().unwrap();
            let snapshot = registry.terminal_snapshot()?;
            (registry.terminal_record(terminal_id)?, snapshot.revision)
        };
        let Some(terminal) = terminal else {
            return Ok(None);
        };
        let state = self.state.lock().unwrap();
        let surface = self
            .catalog_terminal_by_host(&state, terminal_id)?
            .and_then(|runtime| terminal_placement_for_runtime(&state, &runtime));
        Ok(Some(TerminalResolution { surface, terminal, terminal_revision }))
    }

    /// Atomically resolve, incarnation-check, and remove a hosted terminal by
    /// process-stable identity. The host is terminated only after the state
    /// lock has made the removal authoritative for this daemon generation.
    pub fn close_terminal(
        &self,
        terminal_id: &str,
        terminal_incarnation: &str,
    ) -> anyhow::Result<TerminalCloseResult> {
        self.close_terminal_with_mutation(
            terminal_id,
            Some(terminal_incarnation),
            None,
            None,
            &WorkspaceMutation::local("cmux-tui"),
        )
    }

    pub fn close_terminal_with_mutation(
        &self,
        terminal_id: &str,
        terminal_incarnation: Option<&str>,
        expected_generation: Option<&str>,
        expected_revision: Option<u64>,
        mutation: &WorkspaceMutation,
    ) -> anyhow::Result<TerminalCloseResult> {
        validate_terminal_hex(terminal_id, "invalid_terminal_id")?;
        if let Some(incarnation) = terminal_incarnation {
            validate_terminal_hex(incarnation, "invalid_terminal_incarnation")?;
        }
        let (commit, terminal_incarnation, public_id, notify_public_id) = {
            let mut registry = self.workspace_registry.lock().unwrap();
            let public_id = registry.terminal_resource_id(terminal_id)?;
            let commit = registry.close_terminal(
                mutation,
                expected_generation,
                expected_revision,
                terminal_id,
                terminal_incarnation,
            )?;
            let newly_closed =
                !commit.replayed && !commit.result["already_closed"].as_bool().unwrap_or(false);
            if newly_closed {
                self.emit_terminal_registry_changed(&registry, commit.revision);
            }
            let incarnation =
                registry.terminal_record(terminal_id)?.and_then(|terminal| terminal.incarnation);
            (commit, incarnation, public_id.clone(), newly_closed.then_some(public_id).flatten())
        };
        self.notify_terminal_exit_waiters(notify_public_id);
        let (target, removed, runtime, changed_screens, empty_revision) = {
            let mut state = self.state.lock().unwrap();
            let catalog_public_id = public_id.or_else(|| {
                state.terminal_catalog.iter().find_map(|(public_id, surface)| {
                    self.resource_terminal_host_identity(surface)
                        .is_some_and(|identity| identity.terminal_id == terminal_id)
                        .then(|| public_id.clone())
                })
            });
            let runtime = catalog_public_id
                .as_ref()
                .and_then(|public_id| state.terminal_catalog.get(public_id))
                .cloned();
            // The durable close has committed. From this point cleanup must
            // finish even if an in-memory host incarnation was stale; leaving
            // a live runtime behind would contradict the terminal tombstone.
            let content_id = catalog_public_id.map(ContentPublicId::Terminal);
            let mut targets = content_id
                .as_ref()
                .map(|content_id| state.placements_of_content(content_id).to_vec())
                .unwrap_or_default();
            if targets.is_empty() {
                targets.extend(state.surfaces.iter().filter_map(|(surface_id, surface)| {
                    self.resource_terminal_host_identity(surface)
                        .is_some_and(|identity| identity.terminal_id == terminal_id)
                        .then_some(*surface_id)
                }));
            }
            let target = targets.first().copied();
            let changed_screens = unique_screen_ids(
                targets.iter().filter_map(|surface| surface_screen_id(&state, *surface)),
            );
            let removed = if let Some(runtime) = runtime.as_ref() {
                remove_terminal_runtime_from_state(self, &mut state, runtime).0
            } else {
                let mut removed = Vec::with_capacity(targets.len());
                let mut split_index_dirty = false;
                for target in targets {
                    let (surface, topology_changed) = remove_surface(self, &mut state, target);
                    split_index_dirty |= topology_changed;
                    if let Some(surface) = surface {
                        removed.push(surface);
                    }
                }
                if split_index_dirty {
                    Self::rebuild_split_screen_index(&mut state);
                }
                removed
            };
            let empty_revision = state.workspaces.is_empty().then_some(state.workspace_revision);
            (target, removed, runtime, changed_screens, empty_revision)
        };
        for surface in removed {
            self.purge_surface_side_tables(surface.id);
        }
        let had_runtime = runtime.is_some();
        if let Some(runtime) = runtime {
            self.purge_terminal_runtime_side_tables(&runtime);
            self.terminate_terminal_runtime(&runtime);
        }
        if target.is_some() {
            self.emit(MuxEvent::TreeChanged);
        }
        for screen in changed_screens {
            self.emit(MuxEvent::LayoutChanged(screen));
        }
        if !had_runtime {
            self.terminate_discovered_terminal_host(terminal_id, terminal_incarnation.as_deref());
        }
        self.emit_empty_if_current(empty_revision);
        Ok(TerminalCloseResult {
            surface: target,
            terminal_id: terminal_id.to_string(),
            terminal_incarnation,
            already_closed: commit.result["already_closed"].as_bool().unwrap_or(commit.replayed),
            terminal_revision: commit.revision,
        })
    }

    /// A host can become Running before its topology binding is built. Keep
    /// the durable lifecycle transition ahead of in-memory removal so a crash
    /// at any point cannot resurrect an unbound Running terminal on restart.
    fn fail_hosted_terminal_attachment(
        &self,
        surface: &Arc<Surface>,
        _operation: &str,
        reason: &str,
    ) -> anyhow::Result<()> {
        let Some(identity) = self.resource_terminal_host_identity(surface) else {
            let removed = {
                let mut state = self.state.lock().unwrap();
                remove_terminal_runtime_from_state(self, &mut state, surface).0
            };
            for placement in removed {
                self.purge_surface_side_tables(placement.id);
            }
            self.purge_terminal_runtime_side_tables(surface);
            if !surface.is_dead() {
                surface.kill();
            }
            return Ok(());
        };
        self.persist_terminal_exit(
            &identity.terminal_id,
            Some(&identity.incarnation),
            &TerminalExit::unknown(reason),
        )?;
        let removed = {
            let mut state = self.state.lock().unwrap();
            remove_terminal_runtime_from_state(self, &mut state, surface).0
        };
        for placement in removed {
            self.purge_surface_side_tables(placement.id);
        }
        self.purge_terminal_runtime_side_tables(surface);
        if !surface.is_dead() {
            surface.kill();
        }
        Ok(())
    }

    pub(crate) fn terminate_discovered_terminal_host(
        &self,
        terminal_id: &str,
        incarnation: Option<&str>,
    ) {
        #[cfg(unix)]
        {
            let root = self.surface_options.lock().unwrap().terminal_host_root.clone();
            let Some(root) = root else { return };
            let Ok(records) = crate::terminal_host_runtime::load_terminal_host_records(&root)
            else {
                return;
            };
            for (path, record) in records {
                if record.terminal_id == terminal_id
                    && incarnation.is_none_or(|expected| record.incarnation == expected)
                    && !terminate_host_record(record.clone(), path.clone())
                {
                    schedule_terminal_host_record_cleanup(record, path);
                }
            }
            let record_path = root.join(format!("{terminal_id}.json"));
            let _ = acknowledge_terminal_exit_sidecar(&record_path, terminal_id, incarnation);
        }
        #[cfg(not(unix))]
        let _ = (terminal_id, incarnation);
    }

    fn terminate_terminal_runtime(&self, runtime: &Arc<Surface>) {
        let identity = self.resource_terminal_host_identity(runtime);
        #[cfg(unix)]
        let acknowledged = match runtime
            .terminate_host_and_wait_for_exit(Instant::now() + TERMINAL_HOST_CLOSE_WAIT)
        {
            Ok(Some((path, exit))) => acknowledge_exact_terminal_host_exit(&path, &exit),
            Ok(None) => false,
            Err(error) => {
                if let Some(identity) = identity.as_ref() {
                    eprintln!(
                        "cmux-tui: terminal {} close could not await host exit: {error:#}",
                        identity.terminal_id
                    );
                }
                false
            }
        };
        runtime.kill();
        #[cfg(unix)]
        if !acknowledged && let Some(identity) = identity {
            self.terminate_discovered_terminal_host(
                &identity.terminal_id,
                Some(&identity.incarnation),
            );
        }
        #[cfg(not(unix))]
        let _ = identity;
    }

    /// Run `f` with the session state.
    ///
    /// The state lock is held for the duration of `f`; do not call back
    /// into `Mux` methods that take it (`surface()`, `close_pane()`, ...).
    pub fn with_state<R>(&self, f: impl FnOnce(&State) -> R) -> R {
        f(&self.state.lock().unwrap().value)
    }

    /// Read a derived legacy tree snapshot and its protocol-v7 revision under
    /// one mutex acquisition. This revision includes presentation-like global
    /// selection and zoom fields that are intentionally absent from v8's
    /// structural topology journal.
    pub fn with_state_snapshot<R>(&self, f: impl FnOnce(&State) -> R) -> CanonicalSnapshot<R> {
        let canonical = self.state.lock().unwrap();
        CanonicalSnapshot {
            topology_revision: canonical.legacy_topology_revision,
            state: f(&canonical.value),
        }
    }

    /// Protocol-v7 revision for the complete legacy workspace tree.
    pub fn topology_revision(&self) -> u64 {
        self.state.lock().unwrap().legacy_topology_revision
    }

    /// Protocol-v8 structural revision used by topology snapshots and resume.
    pub fn canonical_topology_revision(&self) -> u64 {
        self.state.lock().unwrap().topology.revision()
    }

    /// Look up the stable result of a retained caller idempotency key. The
    /// server transaction lane can use this before invoking a mutation; key
    /// plumbing into protocol commands remains intentionally separate.
    pub(crate) fn durable_idempotency_result(
        &self,
        key: &str,
    ) -> Option<PersistedIdempotencyResult> {
        self.state
            .lock()
            .unwrap()
            .idempotency_results
            .iter()
            .find(|result| result.key == key)
            .cloned()
    }

    fn canonical_mutation_start(
        &self,
        state: &CanonicalState,
        expectation: CanonicalMutationExpectation,
        operation: &str,
        payload_digest: &str,
    ) -> anyhow::Result<CanonicalMutationStart> {
        if expectation.request_id.is_nil() {
            anyhow::bail!("canonical mutation request_id must be nonzero");
        }
        if expectation.daemon_instance_id != self.daemon_instance_id
            || expectation.session_id != self.session_id
        {
            anyhow::bail!(
                "canonical mutation authority changed: expected daemon {} session {}, current daemon {} session {}",
                expectation.daemon_instance_id,
                expectation.session_id,
                self.daemon_instance_id,
                self.session_id
            );
        }
        if payload_digest.len() != 64
            || !payload_digest.bytes().all(|byte| byte.is_ascii_hexdigit())
        {
            anyhow::bail!("canonical mutation payload digest is invalid");
        }
        let key = format!("canonical:{operation}:{payload_digest}:{}", expectation.request_id);
        if let Some(result) = state.idempotency_results.iter().find(|result| result.key == key) {
            if result.payload_digest != payload_digest {
                anyhow::bail!("canonical mutation retained payload digest is inconsistent");
            }
            let revision = result.committed_topology_revision;
            return Ok(CanonicalMutationStart::Replay {
                receipt: CanonicalMutationReceipt {
                    request_id: expectation.request_id,
                    daemon_instance_id: self.daemon_instance_id,
                    session_id: self.session_id,
                    base_revision: revision.saturating_sub(1),
                    revision,
                    replayed: true,
                },
                result: result.clone(),
            });
        }
        let request_suffix = format!(":{}", expectation.request_id);
        if let Some(previous) = state.idempotency_results.iter().find(|result| {
            result.key.starts_with("canonical:") && result.key.ends_with(&request_suffix)
        }) {
            let same_operation = previous.key.strip_prefix("canonical:").is_some_and(|suffix| {
                suffix.starts_with(operation)
                    && suffix.as_bytes().get(operation.len()) == Some(&b':')
            });
            if same_operation {
                anyhow::bail!("canonical mutation request_id payload changed");
            }
            anyhow::bail!("canonical mutation request_id was already used by another operation");
        }
        let revision = state.topology.revision();
        if revision != expectation.expected_revision {
            anyhow::bail!(
                "canonical mutation revision changed: expected {}, current {}",
                expectation.expected_revision,
                revision
            );
        }
        Ok(CanonicalMutationStart::Fresh { key })
    }

    fn commit_canonical_mutation(
        &self,
        state: &mut CanonicalState,
        operation: TopologyOperation,
        targets: TopologyTargets,
        key: String,
    ) -> CanonicalMutationReceipt {
        let request_id = key
            .rsplit(':')
            .next()
            .and_then(|value| value.parse().ok())
            .expect("canonical idempotency key ends in request UUID");
        let delta = state.commit_topology_with_idempotency(operation, targets, key);
        CanonicalMutationReceipt {
            request_id,
            daemon_instance_id: self.daemon_instance_id,
            session_id: self.session_id,
            base_revision: delta.base_revision,
            revision: delta.revision,
            replayed: false,
        }
    }

    /// Capture both public revisions atomically for identity and liveness
    /// responses.
    pub fn topology_revisions(&self) -> (u64, u64) {
        let canonical = self.state.lock().unwrap();
        (canonical.legacy_topology_revision, canonical.topology.revision())
    }

    #[cfg(test)]
    fn topology_size_computations(&self) -> usize {
        self.state.lock().unwrap().topology.size_computations()
    }

    #[cfg(test)]
    pub(crate) fn topology_subscriber_slots(&self) -> usize {
        self.state.lock().unwrap().topology.subscriber_slots()
    }

    pub fn topology_snapshot(&self) -> TopologySnapshot {
        let canonical = self.state.lock().unwrap();
        canonical.topology.snapshot(&canonical.value)
    }

    pub fn subscribe_topology(
        &self,
        daemon_instance_id: DaemonInstanceId,
        session_id: SessionId,
        revision: u64,
    ) -> TopologyResume {
        self.state.lock().unwrap().topology.subscribe(daemon_instance_id, session_id, revision)
    }

    pub fn surface_count(&self) -> usize {
        self.state.lock().unwrap().surfaces.len()
    }

    pub fn surface_notification(&self, surface: SurfaceId) -> Option<SurfaceNotification> {
        self.surface_notifications_for_reader(LEGACY_TERMINAL_ACTIVITY_READER_UUID).remove(&surface)
    }

    pub fn surface_notifications(&self) -> HashMap<SurfaceId, SurfaceNotification> {
        self.surface_notifications_for_reader(LEGACY_TERMINAL_ACTIVITY_READER_UUID)
    }

    pub(crate) fn surface_notifications_for_reader(
        &self,
        reader_uuid: uuid::Uuid,
    ) -> HashMap<SurfaceId, SurfaceNotification> {
        let state = self.state.lock().unwrap();
        state
            .surfaces
            .iter()
            .filter_map(|(surface_id, surface)| {
                let fact = state.terminal_activity.fact(surface.uuid)?;
                state.terminal_activity.is_unread(reader_uuid, surface.uuid).then_some((
                    *surface_id,
                    SurfaceNotification {
                        notification: fact.notification,
                        level: fact.level,
                        unread: true,
                    },
                ))
            })
            .collect()
    }

    pub fn clear_surface_notification(&self, surface: SurfaceId) -> bool {
        let cleared = self.mark_legacy_surface_seen(Some(surface));
        if cleared {
            self.emit(MuxEvent::TreeChanged);
        }
        cleared
    }

    fn active_surface_in_state(state: &State) -> Option<SurfaceId> {
        let pane = state.active_pane()?;
        state.panes.get(&pane)?.active_surface()
    }

    pub fn active_surface(&self) -> Option<SurfaceId> {
        self.with_state(Self::active_surface_in_state)
    }

    /// Scroll one backend-owned view without mutating the terminal runtime
    /// shared by the terminal's other placements.
    pub fn scroll_surface_viewport(&self, surface: &Surface, delta: isize) -> anyhow::Result<()> {
        let before = surface.view_scrollbar();
        let after = surface.view_scroll_delta(delta)?;
        if after != before
            && let Some(scrollbar) = after
        {
            self.emit(MuxEvent::ScrollChanged {
                surface: surface.id,
                offset: scrollbar.offset,
                at_bottom: !scrollbar.scrolled_back(),
            });
        }
        Ok(())
    }

    fn clear_viewed_notification(&self, surface: Option<SurfaceId>) {
        let _ = self.mark_legacy_surface_seen(surface);
    }

    fn mark_legacy_surface_seen(&self, surface: Option<SurfaceId>) -> bool {
        let Some(surface) = surface else { return false };
        let mut state = self.state.lock().unwrap();
        let Some(surface_uuid) = state.surfaces.get(&surface).map(|surface| surface.uuid) else {
            return false;
        };
        let changed = state
            .terminal_activity
            .mark_latest_seen(LEGACY_TERMINAL_ACTIVITY_READER_UUID, surface_uuid)
            .unwrap_or_else(|error| {
                eprintln!("cmux-tui: legacy activity receipt rejected: {error}");
                None
            })
            .is_some_and(|(_, changed)| changed);
        if changed {
            state.persist_terminal_activity("legacy-seen");
        }
        changed
    }

    pub fn post_notification(
        &self,
        title: String,
        body: String,
        level: NotificationLevel,
        surface: Option<SurfaceId>,
    ) -> anyhow::Result<u64> {
        let id = self.next_notification_id()?;
        let mut has_activity = false;
        if let Some(surface) = surface {
            let mut state = self.state.lock().unwrap();
            let surface_uuid = state
                .surfaces
                .get(&surface)
                .map(|surface| surface.uuid)
                .ok_or_else(|| anyhow::anyhow!("unknown surface {surface}"))?;
            let fact = state.terminal_activity.record_notification(surface_uuid, id, level)?;
            if Self::active_surface_in_state(&state) == Some(surface) {
                state.terminal_activity.mark_seen(
                    LEGACY_TERMINAL_ACTIVITY_READER_UUID,
                    surface_uuid,
                    fact.sequence,
                )?;
            }
            state.persist_terminal_activity("notification");
            // Publish while the canonical lock still establishes mutation
            // order. A later receipt can never overtake its activity fact.
            self.emit(MuxEvent::TerminalActivity(fact));
            has_activity = true;
        }
        self.emit(MuxEvent::Notification(NotificationEvent {
            notification: id,
            title,
            body,
            level,
            surface: surface.clone(),
        }));
        if has_activity {
            self.emit(MuxEvent::TreeChanged);
        }
        Ok(id)
    }

    pub fn terminal_activity_snapshot(
        &self,
        reader_uuid: uuid::Uuid,
    ) -> anyhow::Result<TerminalActivitySnapshot> {
        if reader_uuid.is_nil() {
            anyhow::bail!("terminal activity reader must be a non-nil UUID");
        }
        Ok(self.state.lock().unwrap().terminal_activity.snapshot(reader_uuid))
    }

    pub fn mark_terminal_seen(
        &self,
        reader_uuid: uuid::Uuid,
        surface_uuid: SurfaceUuid,
        activity_sequence: u64,
    ) -> anyhow::Result<TerminalActivityReadReceipt> {
        let receipt = {
            let mut state = self.state.lock().unwrap();
            if state.indexed_surface_id_by_uuid(surface_uuid).is_none() {
                anyhow::bail!("unknown surface UUID {surface_uuid}");
            }
            let (receipt, changed) =
                state.terminal_activity.mark_seen(reader_uuid, surface_uuid, activity_sequence)?;
            if changed {
                state.persist_terminal_activity("seen");
                // Keep receipt delivery ordered behind the persisted fact and
                // any earlier receipt serialized by this same state lock.
                self.emit(MuxEvent::TerminalActivityReceipt(receipt));
            }
            receipt
        };
        Ok(receipt)
    }

    pub fn resource_notifications(&self, limit: usize) -> Vec<ResourceNotification> {
        let mut notifications = self
            .notification_ledger
            .lock()
            .unwrap()
            .iter()
            .rev()
            .take(limit.min(256))
            .cloned()
            .collect::<Vec<_>>();
        let state = self.state.lock().unwrap();
        for notification in &mut notifications {
            if let Some(terminal_id) = &notification.terminal_id {
                notification.surface = state
                    .placements_of_content(&ContentPublicId::Terminal(terminal_id.clone()))
                    .first()
                    .copied()
                    .or_else(|| state.terminal_catalog.get(terminal_id).map(|surface| surface.id));
            }
        }
        notifications
    }

    pub fn report_agent(
        &self,
        surface: SurfaceId,
        state: AgentState,
        source: AgentSource,
        session: Option<String>,
    ) -> anyhow::Result<AgentRecord> {
        let mutation = WorkspaceMutation::new(
            format!("raw-agent-{}", crate::workspace_registry::new_uuid_v4()),
            "raw-control",
        )?;
        let fingerprint = serde_json::json!({
            "operation":"agent.report",
            "surface":surface,
            "state":state.as_str(),
            "source":source.as_str(),
            "source_session":session,
        });
        let (_, record) = self.commit_agent_report(
            AgentReportTarget::Surface(surface),
            state,
            source,
            session,
            None,
            &mutation,
            &fingerprint,
        )?;
        record.context("fresh raw agent report unexpectedly replayed")
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn resource_report_agent_selected(
        &self,
        selectors: crate::ResourceSelectors,
        terminal_id: &TerminalPublicId,
        agent_state: AgentState,
        source: AgentSource,
        source_session: Option<String>,
        expected_revision: Option<u64>,
        mutation: &WorkspaceMutation,
    ) -> anyhow::Result<ResourcePatchCommit> {
        let fingerprint = serde_json::json!({
            "operation":"agent.report",
            "selectors":selectors,
            "terminal_id":terminal_id,
            "state":agent_state.as_str(),
            "source":source.as_str(),
            "source_session":source_session,
        });
        self.commit_agent_report(
            AgentReportTarget::Resource { selectors: &selectors, terminal_id },
            agent_state,
            source,
            source_session,
            expected_revision,
            mutation,
            &fingerprint,
        )
        .map(|(commit, _)| commit)
    }

    #[allow(clippy::too_many_arguments)]
    fn commit_agent_report(
        &self,
        target: AgentReportTarget<'_>,
        agent_state: AgentState,
        source: AgentSource,
        source_session: Option<String>,
        expected_revision: Option<u64>,
        mutation: &WorkspaceMutation,
        fingerprint: &Value,
    ) -> anyhow::Result<(ResourcePatchCommit, Option<AgentRecord>)> {
        let mut registry = self.workspace_registry.lock().unwrap();
        if let Some(replay) =
            registry.replay_resource_patch(mutation, "agent.report", fingerprint)?
        {
            return Ok((replay, None));
        }
        let mut state = self.state.lock().unwrap();
        let (surface, terminal_id) = match target {
            AgentReportTarget::Surface(surface) => {
                let runtime = state
                    .surfaces
                    .get(&surface)
                    .or_else(|| state.terminal_runtime_by_id(surface))
                    .with_context(|| format!("unknown surface {surface}"))?;
                let identity = runtime.resource_identity().with_context(|| {
                    format!("surface {surface} has no durable resource identity")
                })?;
                let ContentPublicId::Terminal(terminal_id) = &identity.content_id else {
                    anyhow::bail!("surface {surface} is not a terminal");
                };
                (surface, terminal_id.clone())
            }
            AgentReportTarget::Resource { selectors, terminal_id } => {
                self.resolve_resource_path_in_state(
                    &state,
                    &registry,
                    crate::ResourceTarget::Session,
                    selectors,
                )
                .map_err(anyhow::Error::new)?;
                let surface = state
                    .placements_of_content(&ContentPublicId::Terminal((*terminal_id).clone()))
                    .first()
                    .copied()
                    .or_else(|| state.terminal_catalog.get(terminal_id).map(|surface| surface.id))
                    .with_context(|| format!("unknown terminal {terminal_id}"))?;
                (surface, (*terminal_id).clone())
            }
        };
        let now = now_ms();
        let mut records = self.agent_records.lock().unwrap();
        let record = match records.get(&terminal_id) {
            Some(existing)
                if existing.source == AgentSource::Hook && source == AgentSource::Socket =>
            {
                existing.clone()
            }
            _ => TerminalAgentRecord {
                state: agent_state,
                source,
                session: source_session,
                updated_at_ms: now,
            },
        };
        let digest = Sha256::digest(format!("cmux.protocol/2/agent/{terminal_id}").as_bytes());
        let payload = digest[..16].iter().map(|byte| format!("{byte:02x}")).collect::<String>();
        let agent_id =
            AgentPublicId::parse(format!("agent_{payload}")).map_err(anyhow::Error::new)?;
        let session_id = registry.session_id().clone();
        let value = serde_json::json!({
            "id":agent_id,
            "session_id":session_id,
            "terminal_id":terminal_id,
            "state":record.state.as_str(),
            "source":record.source.as_str(),
            "updated_at_ms":record.updated_at_ms.to_string(),
            "source_session":record.session,
        });
        let deltas = serde_json::json!([{
            "kind":"upsert",
            "sequence":0,
            "resource":"agent",
            "id":agent_id,
            "value":value,
        }]);
        let commit = registry.commit_agent_projection(
            mutation,
            fingerprint,
            expected_revision,
            &terminal_id,
            &value,
            &deltas,
        )?;
        state.resource_revision = commit.revision;
        if !commit.replayed {
            records.insert(terminal_id.clone(), record.clone());
        }
        drop(records);
        drop(state);
        drop(registry);
        if !commit.replayed {
            self.publish_resource_event();
        }
        Ok((
            commit,
            Some(AgentRecord {
                surface,
                terminal_id,
                state: record.state,
                source: record.source,
                session: record.session,
                updated_at_ms: record.updated_at_ms,
            }),
        ))
    }

    /// Drop per-surface metadata for a surface that has left the tree.
    /// `SurfaceId` is monotonic, so without this every closed tab would
    /// leak an entry forever and `list-agents` would keep reporting dead
    /// surfaces as live agents.
    fn purge_surface_side_tables(&self, surface: SurfaceId) {
        self.agent_records.lock().unwrap().remove(&surface);
        let mut sizing = self.client_sizing.lock().unwrap();
        sizing.surfaces.remove(&surface);
        sizing.report_order.retain(|(reported_surface, _), _| *reported_surface != surface);
        sizing.policies.remove(&surface);
        sizing.terminal_runtime_by_placement.remove(&surface);
        sizing.terminal_authorities.retain(|_, authority| authority.placement != surface);
        drop(sizing);
        self.placement_notifications.lock().unwrap().remove(&surface);
    }

    fn purge_terminal_side_tables(&self, terminal_id: &TerminalPublicId) {
        self.agent_records.lock().unwrap().remove(terminal_id);
        self.terminal_notifications.lock().unwrap().remove(terminal_id);
    }

    fn purge_terminal_runtime_side_tables(&self, runtime: &Surface) {
        if let Some(runtime_id) = runtime.terminal_runtime_id() {
            self.reserved_in_process_terminals.lock().unwrap().remove(&runtime_id);
            let _cell_pixel_lifecycle = self.cell_pixel_lifecycle.lock().unwrap();
            let mut pending = self.pending_cell_pixels.lock().unwrap();
            if let Some(update) = pending.as_mut() {
                update.failures.remove(&runtime_id);
                if update.failures.is_empty() {
                    let target = update.target;
                    *self.cell_pixels.lock().unwrap() = target;
                    *pending = None;
                }
            }
        }
        if let Some(terminal_id) = runtime.terminal_public_id() {
            self.purge_terminal_side_tables(terminal_id);
        }
    }

    pub fn list_agents(
        &self,
        surface: Option<SurfaceId>,
        state: Option<AgentState>,
    ) -> Vec<AgentRecord> {
        let records = self.agent_records.lock().unwrap().clone();
        let state_snapshot = self.state.lock().unwrap();
        let requested_terminal = surface.and_then(|surface| {
            state_snapshot
                .surfaces
                .get(&surface)
                .or_else(|| state_snapshot.terminal_runtime_by_id(surface))
                .and_then(|surface| surface.terminal_public_id().cloned())
        });
        let mut records = records
            .into_iter()
            .filter_map(|(terminal_id, record)| {
                let representative = state_snapshot
                    .placements_of_content(&ContentPublicId::Terminal(terminal_id.clone()))
                    .first()
                    .copied()
                    .or_else(|| {
                        state_snapshot.terminal_catalog.get(&terminal_id).map(|surface| surface.id)
                    })?;
                Some(AgentRecord {
                    surface: representative,
                    terminal_id,
                    state: record.state,
                    source: record.source,
                    session: record.session,
                    updated_at_ms: record.updated_at_ms,
                })
            })
            .collect::<Vec<_>>();
        records.sort_by(|left, right| left.terminal_id.as_str().cmp(right.terminal_id.as_str()));
        records
            .into_iter()
            .filter(|record| {
                requested_terminal
                    .as_ref()
                    .is_none_or(|terminal_id| &record.terminal_id == terminal_id)
            })
            .filter(|record| state.is_none_or(|state| record.state == state))
            .collect()
    }

    pub fn shutdown(&self) {
        let renderer_presentations = self.renderer_presentations.lock().unwrap().take_all();
        for runtime in renderer_presentations {
            let _operation = runtime.operation.lock().unwrap();
            if let Some(scene) = runtime.begin_removal() {
                scene.canceled.store(true, Ordering::Release);
                scene.control.detach();
            }
        }
        // Drop the producer first so the lossless dispatcher channel closes,
        // then join its one owned consumer before tearing down surface state.
        self.renderer_scene_dispatcher.lock().unwrap().take();
        self.renderer_supervisor.lock().unwrap().take();
        self.renderer_event_dispatcher.lock().unwrap().take();
        let surfaces = self.state.lock().unwrap().surfaces.values().cloned().collect::<Vec<_>>();
        for surface in surfaces {
            surface.shutdown_for_daemon();
        }
        if let Some(runtime) = self.browser_runtime.lock().unwrap().take() {
            runtime.shutdown();
        }
    }

    /// Install the process owner before accepting presentation commands.
    /// cmuxd retains this handle so Swift app restarts do not affect workers.
    pub fn install_renderer_supervisor(
        self: &Arc<Self>,
        config: RendererSupervisorConfig,
    ) -> anyhow::Result<()> {
        let mut slot = self.renderer_supervisor.lock().unwrap();
        let mut dispatcher_slot = self.renderer_event_dispatcher.lock().unwrap();
        if slot.is_some() || dispatcher_slot.is_some() {
            anyhow::bail!("renderer supervisor is already installed");
        }
        let dispatcher = RendererEventDispatcher::start(Arc::downgrade(self))?;
        let supervisor = Arc::new(RendererSupervisor::start(config)?);
        let sender = dispatcher.sender();
        supervisor.set_event_handler(Arc::new(move |event| {
            // Blocking preserves every event and its coordinator order. The
            // dedicated consumer performs no supervisor RPC, so saturation
            // applies bounded backpressure without a callback deadlock.
            let _ = sender.send(event);
        }));
        *dispatcher_slot = Some(dispatcher);
        *slot = Some(supervisor);
        Ok(())
    }

    #[cfg(test)]
    fn install_renderer_supervisor_for_test(&self, supervisor: Arc<dyn RendererSupervisorServing>) {
        let mut slot = self.renderer_supervisor.lock().unwrap();
        assert!(slot.is_none(), "renderer supervisor is already installed");
        *slot = Some(supervisor);
    }

    pub(crate) fn set_renderer_presentation_workspace(
        &self,
        presentation_id: crate::PresentationId,
        workspace_uuid: Option<WorkspaceUuid>,
    ) -> Result<(), RendererSupervisorError> {
        let supervisor = self.renderer_supervisor.lock().unwrap().clone();
        match supervisor {
            Some(supervisor) => {
                supervisor.set_presentation_workspace(presentation_id, workspace_uuid)
            }
            None => Ok(()),
        }
    }

    pub(crate) fn remove_renderer_presentation(
        &self,
        presentation_id: crate::PresentationId,
    ) -> anyhow::Result<()> {
        self.remove_renderer_presentation_with_timeout(
            presentation_id,
            RENDERER_PRESENTATION_REMOVAL_TIMEOUT,
        )
    }

    fn remove_renderer_presentation_with_timeout(
        &self,
        presentation_id: crate::PresentationId,
        removal_timeout: Duration,
    ) -> anyhow::Result<()> {
        let runtime = self.renderer_presentations.lock().unwrap().remove(&presentation_id);
        let supervisor = self.renderer_supervisor.lock().unwrap().clone();
        let retirement = runtime.as_ref().map_or(Ok(()), |runtime| {
            self.retire_renderer_runtime_for_close(runtime, supervisor.as_deref(), removal_timeout)
        });
        self.renderer_presentation_generations.lock().unwrap().remove(&presentation_id);
        let visibility = match supervisor {
            Some(supervisor) => {
                supervisor.remove_presentation(presentation_id).map_err(anyhow::Error::from)
            }
            None => Ok(()),
        };
        retirement?;
        visibility
    }

    fn retire_renderer_runtime_for_close(
        &self,
        runtime: &RendererPresentationRuntime,
        supervisor: Option<&dyn RendererSupervisorServing>,
        removal_timeout: Duration,
    ) -> anyhow::Result<()> {
        let _operation = runtime.operation.lock().unwrap();
        let scene = runtime.begin_removal();
        let removal = runtime.removal();
        let lifetime = RendererPresentationLifetime {
            presentation_id: removal.presentation_id,
            presentation_generation: removal.presentation_generation,
        };
        let retained_pending =
            self.renderer_removal_waiters.lock().unwrap().get(&lifetime).cloned();
        let renderer_epoch = match (&retained_pending, &scene, runtime.published_epoch()) {
            (Some(pending), _, _) => pending.renderer_epoch,
            (None, Some(scene), _) => scene.renderer_epoch,
            (None, None, Some(renderer_epoch)) => renderer_epoch,
            (None, None, None) => return Ok(()),
        };
        let Some(supervisor) = supervisor else {
            if let Some(scene) = scene {
                scene.canceled.store(true, Ordering::Release);
                scene.control.detach();
            }
            return Ok(());
        };
        let Some((_, pending)) = self.renderer_removal_waiter(runtime, renderer_epoch)? else {
            if let Some(scene) = scene {
                scene.canceled.store(true, Ordering::Release);
                scene.control.detach();
            }
            return Ok(());
        };
        if let Some(scene) = scene.as_ref() {
            scene.canceled.store(true, Ordering::Release);
        }
        let send_result = if pending.is_quiesced() {
            Ok(())
        } else {
            supervisor.send_if_epoch(
                runtime.workspace_uuid,
                renderer_epoch,
                vec![RendererControlMessage::RemovePresentation(removal)],
            )
        };
        if let Some(scene) = scene {
            scene.control.detach();
        }
        let mut quiesced = pending.wait_until_quiesced(removal_timeout);
        if !quiesced {
            quiesced = supervisor.retire_if_epoch(runtime.workspace_uuid, renderer_epoch)?;
            if quiesced {
                self.complete_renderer_removal(lifetime, &pending);
            }
        }
        if !quiesced {
            if let Err(error) = send_result {
                return Err(error.into());
            }
            anyhow::bail!("renderer presentation removal did not reach exact quiescence");
        }
        self.complete_renderer_removal(lifetime, &pending);
        Ok(())
    }

    pub fn renderer_worker_statuses(&self) -> Vec<RendererWorkerStatus> {
        self.renderer_supervisor
            .lock()
            .unwrap()
            .as_ref()
            .map(|supervisor| supervisor.statuses())
            .unwrap_or_default()
    }

    pub fn renderer_worker_status(
        &self,
        workspace_uuid: WorkspaceUuid,
    ) -> Result<Option<RendererWorkerStatus>, RendererSupervisorError> {
        let supervisor = self.renderer_supervisor.lock().unwrap().clone();
        match supervisor {
            Some(supervisor) => supervisor.workspace_status(workspace_uuid),
            None => Ok(None),
        }
    }

    fn complete_renderer_removal(
        &self,
        lifetime: RendererPresentationLifetime,
        pending: &Arc<PendingRendererPresentationRemoval>,
    ) {
        let presentation_id = presentation_id_from_uuid(lifetime.presentation_id);
        let runtime = self
            .renderer_presentations
            .lock()
            .unwrap()
            .get(&presentation_id)
            .filter(|runtime| {
                runtime.attachment.presentation_generation == lifetime.presentation_generation
            })
            .cloned();
        // Keep the publication proof locked until the waiter disappears. A
        // retry therefore sees either both old facts or both new facts and
        // cannot recreate a waiter after an acknowledgement.
        let mut published = runtime.as_ref().map(|runtime| runtime.published_epoch.lock().unwrap());
        #[cfg(test)]
        if let Some(before_map_erase) =
            self.renderer_removal_before_map_erase.lock().unwrap().take()
        {
            before_map_erase();
        }
        let removed = {
            let mut removals = self.renderer_removal_waiters.lock().unwrap();
            if removals.get(&lifetime).is_some_and(|current| Arc::ptr_eq(current, pending)) {
                removals.remove(&lifetime)
            } else {
                None
            }
        };
        if let Some(removed) = removed {
            self.renderer_release_routes.lock().unwrap().remove(RendererReleaseRouteKey {
                presentation_id,
                presentation_generation: lifetime.presentation_generation,
                renderer_epoch: removed.renderer_epoch,
            });
            if let Some(published) = published.as_mut()
                && **published == Some(removed.renderer_epoch)
            {
                **published = None;
            }
            removed.mark_quiesced();
        }
    }

    fn renderer_removal_waiter(
        &self,
        runtime: &RendererPresentationRuntime,
        renderer_epoch: u64,
    ) -> anyhow::Result<
        Option<(RendererPresentationLifetime, Arc<PendingRendererPresentationRemoval>)>,
    > {
        let removal = runtime.removal();
        let lifetime = RendererPresentationLifetime {
            presentation_id: removal.presentation_id,
            presentation_generation: removal.presentation_generation,
        };
        let published = runtime.published_epoch.lock().unwrap();
        if *published != Some(renderer_epoch) {
            return Ok(None);
        }
        let mut removals = self.renderer_removal_waiters.lock().unwrap();
        if let Some(pending) = removals.get(&lifetime) {
            if !pending.matches(
                runtime.workspace_uuid,
                renderer_epoch,
                removal.terminal_id,
                removal.terminal_epoch,
            ) {
                anyhow::bail!("renderer presentation removal lifetime is already pending");
            }
            return Ok(Some((lifetime, pending.clone())));
        }
        let pending = Arc::new(PendingRendererPresentationRemoval {
            workspace_uuid: runtime.workspace_uuid,
            renderer_epoch,
            terminal_id: removal.terminal_id,
            terminal_epoch: removal.terminal_epoch,
            quiesced: Mutex::new(false),
            changed: std::sync::Condvar::new(),
        });
        removals.insert(lifetime, pending.clone());
        Ok(Some((lifetime, pending)))
    }

    fn complete_renderer_removals_for_worker(
        &self,
        workspace_uuid: WorkspaceUuid,
        renderer_epoch: u64,
    ) {
        let pending = self
            .renderer_removal_waiters
            .lock()
            .unwrap()
            .iter()
            .filter_map(|(lifetime, pending)| {
                (pending.workspace_uuid == workspace_uuid
                    && pending.renderer_epoch == renderer_epoch)
                    .then_some((*lifetime, pending.clone()))
            })
            .collect::<Vec<_>>();
        for (lifetime, pending) in pending {
            self.complete_renderer_removal(lifetime, &pending);
        }
    }

    fn require_renderer_removal_quiescence(
        &self,
        presentation_id: crate::PresentationId,
        supervisor: &dyn RendererSupervisorServing,
    ) -> anyhow::Result<()> {
        let pending = self
            .renderer_removal_waiters
            .lock()
            .unwrap()
            .iter()
            .filter_map(|(lifetime, pending)| {
                (lifetime.presentation_id == presentation_id.as_uuid())
                    .then_some((*lifetime, pending.clone()))
            })
            .collect::<Vec<_>>();
        for (lifetime, pending) in pending {
            let quiesced = pending.is_quiesced()
                || supervisor.retire_if_epoch(pending.workspace_uuid, pending.renderer_epoch)?;
            if quiesced {
                self.complete_renderer_removal(lifetime, &pending);
            }
        }
        if self
            .renderer_removal_waiters
            .lock()
            .unwrap()
            .keys()
            .any(|lifetime| lifetime.presentation_id == presentation_id.as_uuid())
        {
            anyhow::bail!("renderer presentation replacement is blocked by an unquiesced removal");
        }
        Ok(())
    }

    pub(crate) fn configure_renderer_presentation(
        self: &Arc<Self>,
        client: u64,
        presentation_id: crate::PresentationId,
        expected_generation: u64,
        configuration: RendererPresentationConfiguration,
    ) -> anyhow::Result<RendererPresentationReceipt> {
        if configuration.columns == 0 || configuration.rows == 0 {
            anyhow::bail!("renderer terminal columns and rows must be nonzero");
        }
        let presentation = self.presentations.get_for_client(client, presentation_id)?;
        if presentation.generation != expected_generation {
            anyhow::bail!(
                "stale presentation generation {expected_generation}; current generation is {}",
                presentation.generation
            );
        }
        let (workspace_uuid, surface_id, surface) = {
            let state = self.state.lock().unwrap();
            let workspace_id = presentation
                .view
                .workspace
                .ok_or_else(|| anyhow::anyhow!("renderer presentation requires a workspace"))?;
            let surface_id = presentation
                .view
                .tab
                .ok_or_else(|| anyhow::anyhow!("renderer presentation requires a surface"))?;
            let pane_id = state
                .indexed_pane_of(surface_id)
                .ok_or_else(|| anyhow::anyhow!("renderer surface is outside canonical topology"))?;
            let (workspace_index, _) = state
                .indexed_screen_of(pane_id)
                .ok_or_else(|| anyhow::anyhow!("renderer pane is outside canonical topology"))?;
            let workspace = &state.workspaces[workspace_index];
            if workspace.id != workspace_id
                || presentation.view.workspace_uuid != Some(workspace.uuid)
                || presentation.view.surface_uuid != state.surface_uuid(surface_id)
            {
                anyhow::bail!("renderer surface is outside its presentation workspace");
            }
            let surface = state
                .surfaces
                .get(&surface_id)
                .cloned()
                .ok_or_else(|| anyhow::anyhow!("unknown renderer surface {surface_id}"))?;
            Ok::<_, anyhow::Error>((workspace.uuid, surface_id, surface))
        }?;
        let terminal = surface
            .semantic_scene_terminal_identity()
            .ok_or_else(|| anyhow::anyhow!("browser surfaces have no terminal renderer"))?;

        if !self.renderer_presentations.lock().unwrap().admits(presentation_id, workspace_uuid) {
            anyhow::bail!(
                "workspace renderer presentation limit reached (maximum {})",
                MAXIMUM_RENDERER_PRESENTATIONS_PER_WORKSPACE
            );
        }

        let supervisor = self
            .renderer_supervisor
            .lock()
            .unwrap()
            .clone()
            .ok_or_else(|| anyhow::anyhow!("renderer supervisor is not installed"))?;
        self.require_renderer_removal_quiescence(presentation_id, supervisor.as_ref())?;

        self.apply_renderer_configuration_size(
            surface_id,
            client,
            configuration.columns,
            configuration.rows,
        )?;
        let (columns, rows) = surface.size();
        let renderer_generation = {
            let generations = self.renderer_presentation_generations.lock().unwrap();
            match generations.get(&presentation_id).copied() {
                Some(previous) => previous
                    .checked_add(1)
                    .ok_or_else(|| anyhow::anyhow!("renderer presentation generation exhausted"))?
                    .max(presentation.generation),
                None => presentation.generation.max(1),
            }
        };
        let attachment = RendererPresentationAttachment {
            terminal_id: terminal.terminal_id.as_uuid(),
            terminal_epoch: terminal.runtime_epoch,
            presentation_id: presentation_id.as_uuid(),
            presentation_generation: renderer_generation,
            width: configuration.width,
            height: configuration.height,
            backing_scale_factor: configuration.backing_scale_factor,
            pixel_format: configuration.pixel_format,
            color_space: configuration.color_space,
            frame_endpoint_service: configuration.frame_endpoint_service.clone(),
            frame_endpoint_capability: configuration.frame_endpoint_capability.clone(),
            resolved_config_revision: configuration.resolved_config_revision,
            resolved_config: configuration.resolved_config.clone(),
        };
        let mut validator = RendererControlEncoder::new(RendererControlDirection::DaemonToWorker);
        validator.encode(RendererControlMessage::UpsertPresentation(attachment.clone()))?;

        let custom_shader_count = resolved_custom_shader_count(&configuration.resolved_config)?;
        let capture = SemanticSceneCaptureOptions {
            focused: configuration.focused,
            cursor_blink_visible: configuration.cursor_blink_visible,
            custom_shader_count,
            ..SemanticSceneCaptureOptions::default()
        };
        let mut scene_options = SemanticSceneAttachmentOptions::new(
            terminal,
            SemanticScenePresentationIdentity { presentation_id, generation: renderer_generation },
        );
        scene_options.capture = capture;
        scene_options.preedit = configuration.preedit.as_ref().map(RendererPreedit::semantic);
        let scene_attachment = surface.attach_semantic_scene(scene_options)?;
        let minimum_content_sequence = scene_attachment.initial.content_sequence;
        scene_attachment.control.detach();

        // Recheck connection ownership after the potentially expensive full
        // capture so a racing disconnect cannot install an orphan runtime.
        let current = self.presentations.get_for_client(client, presentation_id)?;
        if current.generation != presentation.generation {
            anyhow::bail!("presentation changed while its renderer was attaching");
        }
        let retained_workspace = self
            .renderer_presentations
            .lock()
            .unwrap()
            .get(&presentation_id)
            .map(|runtime| runtime.workspace_uuid);
        supervisor.set_presentation_workspace(presentation_id, Some(workspace_uuid))?;
        match supervisor.workspace_status(workspace_uuid) {
            Ok(Some(_)) => {}
            Ok(None) => {
                supervisor.set_presentation_workspace(presentation_id, retained_workspace)?;
                anyhow::bail!("renderer worker was not created");
            }
            Err(error) => {
                supervisor.set_presentation_workspace(presentation_id, retained_workspace)?;
                return Err(error.into());
            }
        };
        self.require_renderer_removal_quiescence(presentation_id, supervisor.as_ref())?;
        let runtime = Arc::new(RendererPresentationRuntime {
            client,
            workspace_uuid,
            surface: surface.clone(),
            attachment: attachment.clone(),
            capture,
            preedit: Mutex::new(configuration.preedit),
            operation: Mutex::new(()),
            scene: Mutex::new(None),
            activation: Mutex::new(RendererActivationState::default()),
            published_epoch: Mutex::new(None),
            removal_pending: AtomicBool::new(false),
        });
        let previous = {
            let mut runtimes = self.renderer_presentations.lock().unwrap();
            if !runtimes.admits(presentation_id, workspace_uuid) {
                let retained_workspace =
                    runtimes.get(&presentation_id).map(|runtime| runtime.workspace_uuid);
                drop(runtimes);
                supervisor.set_presentation_workspace(presentation_id, retained_workspace)?;
                anyhow::bail!(
                    "workspace renderer presentation limit reached (maximum {})",
                    MAXIMUM_RENDERER_PRESENTATIONS_PER_WORKSPACE
                );
            }
            runtimes.insert(presentation_id, runtime.clone())
        };
        let focus_changed = previous.as_ref().map_or(configuration.focused, |previous| {
            previous.capture.focused != configuration.focused
        });
        if focus_changed {
            surface.terminal_accessibility_focus_changed();
        }
        self.renderer_presentation_generations
            .lock()
            .unwrap()
            .insert(presentation_id, renderer_generation);
        if let Some(previous) = previous {
            self.retire_renderer_runtime(&previous);
        }
        // Publish only the worker identity here. The renderer cannot receive
        // the endpoint or a semantic scene until Swift acknowledges that it
        // installed both NOTE_EXIT and Mach audit-token fences for this epoch.
        let worker = match supervisor.workspace_status(workspace_uuid) {
            Ok(Some(worker)) => worker,
            Ok(None) => {
                self.remove_renderer_runtime_if_current(&runtime);
                anyhow::bail!("renderer worker disappeared while attaching");
            }
            Err(error) => {
                self.remove_renderer_runtime_if_current(&runtime);
                return Err(error.into());
            }
        };
        Ok(RendererPresentationReceipt {
            daemon_instance_id: self.daemon_instance_id,
            worker,
            terminal_id: terminal.terminal_id,
            terminal_epoch: terminal.runtime_epoch,
            presentation_id,
            canonical_presentation_generation: presentation.generation,
            renderer_presentation_generation: renderer_generation,
            minimum_content_sequence,
            width: configuration.width,
            height: configuration.height,
            backing_scale_factor: configuration.backing_scale_factor,
            columns,
            rows,
            pixel_format: configuration.pixel_format,
            color_space: configuration.color_space,
        })
    }

    pub(crate) fn terminal_accessibility_snapshot(
        &self,
        client: u64,
        presentation_id: crate::PresentationId,
        expected_generation: u64,
        expected_content_sequence: u64,
    ) -> anyhow::Result<crate::TerminalAccessibilitySnapshot> {
        let presentation = self.presentations.get_for_client(client, presentation_id)?;
        if presentation.generation != expected_generation {
            anyhow::bail!(
                "stale presentation generation {expected_generation}; current generation is {}",
                presentation.generation
            );
        }
        let surface_uuid = presentation
            .view
            .surface_uuid
            .ok_or_else(|| anyhow::anyhow!("accessibility presentation requires a terminal"))?;
        let surface = self.with_state(|state| {
            let surface_id = state
                .surface_id_by_uuid(surface_uuid)
                .ok_or_else(|| anyhow::anyhow!("unknown terminal {surface_uuid}"))?;
            state
                .surfaces
                .get(&surface_id)
                .cloned()
                .ok_or_else(|| anyhow::anyhow!("unknown terminal {surface_uuid}"))
        })?;
        let runtime = self
            .renderer_presentations
            .lock()
            .unwrap()
            .get(&presentation_id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("accessibility presentation is not rendered"))?;
        if runtime.client != client || runtime.surface.uuid != surface_uuid {
            anyhow::bail!("accessibility presentation authority changed");
        }
        surface.terminal_accessibility_snapshot_at(
            presentation_id,
            presentation.generation,
            runtime.capture.focused,
            expected_content_sequence,
        )
    }

    pub(crate) fn activate_terminal_accessibility_link(
        &self,
        client: u64,
        presentation_id: crate::PresentationId,
        expected_generation: u64,
        terminal_revision: u64,
        content_revision: u64,
        viewport_revision: u64,
        link_id: &str,
    ) -> anyhow::Result<String> {
        let presentation = self.presentations.get_for_client(client, presentation_id)?;
        if presentation.generation != expected_generation {
            anyhow::bail!(
                "stale presentation generation {expected_generation}; current generation is {}",
                presentation.generation
            );
        }
        let surface_uuid = presentation
            .view
            .surface_uuid
            .ok_or_else(|| anyhow::anyhow!("accessibility presentation requires a terminal"))?;
        let surface = self.with_state(|state| {
            let surface_id = state
                .surface_id_by_uuid(surface_uuid)
                .ok_or_else(|| anyhow::anyhow!("unknown terminal {surface_uuid}"))?;
            state
                .surfaces
                .get(&surface_id)
                .cloned()
                .ok_or_else(|| anyhow::anyhow!("unknown terminal {surface_uuid}"))
        })?;
        let runtime = self
            .renderer_presentations
            .lock()
            .unwrap()
            .get(&presentation_id)
            .cloned()
            .ok_or_else(|| anyhow::anyhow!("accessibility presentation is not rendered"))?;
        if runtime.client != client || runtime.surface.uuid != surface_uuid {
            anyhow::bail!("accessibility presentation authority changed");
        }
        surface.activate_terminal_accessibility_link(
            presentation_id,
            presentation.generation,
            runtime.capture.focused,
            terminal_revision,
            content_revision,
            viewport_revision,
            link_id,
        )
    }

